import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab } from '../admin-plans/plans-helpers';
import { accountRows, columnValues, filterControl, selectFilter, expectColumnEqualsOrEmpty, EMPTY_EN, FILTER } from '../admin-plans/plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Trial — Admin Panel → Plans', () => {
  test('Trial ended rows are on Techory Lite with no end date #f109cde8 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openPlansTab(page);
    await expect(accountRows(page).first()).toBeVisible();

    await selectFilter(page, filterControl(page, FILTER.statuses), 'Trial ended');
    await expectColumnEqualsOrEmpty(page, 'Subscription status', 'Trial ended');

    if (await page.getByText(EMPTY_EN, { exact: true }).isVisible()) {
      test.info().annotations.push({ type: 'note', description: 'Строк «Trial ended» нет — проверять нечего.' });
      return;
    }

    // не проверено на сайте: точная подпись тарифа («Techory Lite» или «Lite») — проверяем вхождение «Lite».
    const plans = await columnValues(page, 'Plan');
    expect(plans.filter((p) => !/Lite/.test(p)), 'после конца trial — тариф Techory Lite').toEqual([]);

    const until = await columnValues(page, 'Until');
    expect(until.filter((u) => !/^[—–-]$/.test(u)), 'у «Trial ended» дата Until не показывается («—»)').toEqual([]);
  });
});
